let mut source=BTreeMap::new();for dir in["source","initial-attempt/source"]{let mut files=vec![];walk(&r(dir),&mut files);assert_eq!(files.len(),176);for p in files{let v=encode(&p);assert_eq!(decode(&v),fs::read(&p).unwrap());source.insert(p.strip_prefix(R).unwrap().display().to_string(),v);}}
