let mut proof_artifacts=BTreeMap::new();for(p,h)in read(r("proof-inventory.json")).as_object().unwrap(){assert_eq!(filehash(p),h.as_str().unwrap());let p=Path::new(p);let v=encode(p);assert_eq!(decode(&v),fs::read(p).unwrap());proof_artifacts.insert(p.strip_prefix(R).unwrap().display().to_string(),v);}assert_eq!(proof_artifacts.len(),38);
